// batch81: devToolsLogger — data-driven from batch81_truth.json
// (truth generated by Node vm against the real TS source with a stubbed
// registerDebugChannel capturing handleChange notifications).
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/debugLocation.dart'
    show DebugLocationImpl;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/logging/debugger/devToolsLogger.dart'
    as dl;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/logging/logging.dart'
    show IChangeInformation;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/observables/derived.dart'
    as d;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/observables/observableValue.dart'
    as ov;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/reactions/autorun.dart'
    as au;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/transaction.dart'
    show TransactionImpl;

Map<String, dynamic> _truth() => jsonDecode(
      File('tool/ts2dart/batch81_truth.json').readAsStringSync(),
    ) as Map<String, dynamic>;

DebugLocationImpl _loc(String id, String file, int line, int col) =>
    DebugLocationImpl(file, line, col, id);

Object? _copyAny(Object? v) {
  if (v is Map) return v.map((k, value) => MapEntry(k, _copyAny(value)));
  if (v is List) return [for (final e in v) _copyAny(e)];
  return v;
}

class _Capture {
  _Capture(this.logger) {
    final client = logger.channelClient as Map<String, Object?>;
    final notifications = client['notifications'] as Map<String, Object?>;
    notifications['handleChange'] = (Object? state, bool isFull) {
      states.add(_copyAny(state) as Map);
    };
  }
  final dl.DevToolsLogger logger;
  final List<Map> states = <Map>[];

  void clear() => states.clear();

  Iterable<Map> get instanceStates =>
      states.where((s) => s.containsKey('instances'));

  Map? instanceWith(String key) {
    for (final s in instanceStates) {
      final instances = s['instances'];
      if (instances is Map) {
        for (final inst in instances.values) {
          if (inst is Map && inst.containsKey(key)) return inst;
        }
      }
    }
    return null;
  }

  Map? instanceMatching(bool Function(Object? value) test) {
    for (final s in instanceStates) {
      final instances = s['instances'];
      if (instances is Map) {
        for (final inst in instances.values) {
          if (test(inst)) return instances as Map?;
        }
      }
    }
    return null;
  }
}

Future<void> _flush(Map<String, Object?> notifications) async {
  (notifications['flushUpdates'] as void Function())();
  await Future<void>.delayed(Duration.zero);
}

Map<String, Object?> _notifications(dl.DevToolsLogger logger) =>
    (logger.channelClient as Map<String, Object?>)['notifications']
        as Map<String, Object?>;

void main() {
  group('batch81 DevToolsLogger', () {
    test('singleton', () {
      final t = _truth()['singleton'] as bool;
      expect(
          identical(dl.DevToolsLogger.getInstance(),
              dl.DevToolsLogger.getInstance()),
          t);
    });

    test('observable lifecycle', () async {
      final t = _truth()['observable'] as Map<String, dynamic>;
      final logger = dl.DevToolsLogger.getInstance();
      final cap = _Capture(logger);
      final notifications = _notifications(logger);

      final o = ov.observableValue<int, Object?>('ov', 1);
      logger.handleObservableCreated(o, _loc('loc1', 'file.ts', 10, 5));
      await _flush(notifications);
      cap.clear();

      logger.handleOnListenerCountChanged(o, 1);
      await _flush(notifications);
      final addInst = cap.instanceWith('type');
      cap.clear();

      logger.handleObservableUpdated(o, IChangeInformation(
        hadValue: true, oldValue: 1, newValue: 2, change: null, didChange: true));
      await _flush(notifications);
      final updInst = cap.instanceWith('formattedValue');
      cap.clear();

      logger.handleObservableUpdated(o, IChangeInformation(
        hadValue: true, oldValue: 2, newValue: 2, change: null, didChange: false));
      await _flush(notifications);
      final noChangeStates = cap.states.toList();
      cap.clear();

      logger.handleOnListenerCountChanged(o, 0);
      await _flush(notifications);
      final removedInst = cap.instanceMatching((v) => v == null);
      cap.clear();

      final expAdd = ((t['afterListenerAdd'] as List).first as Map)['state']
          as Map<String, dynamic>;
      final expAddInst = (expAdd['instances'] as Map).values.first as Map;
      expect(addInst, isNotNull);
      expect(addInst!['type'], expAddInst['type']);
      expect(addInst['name'], isA<String>());
      expect(addInst['declarationId'], isA<int>());
      expect(addInst['instanceId'], isA<int>());

      final expUpd = ((t['afterUpdate'] as List).first as Map)['state']
          as Map<String, dynamic>;
      final expUpdInst = (expUpd['instances'] as Map).values.first as Map;
      expect(updInst, isNotNull);
      expect(updInst!['formattedValue'], expUpdInst['formattedValue']);

      expect(noChangeStates, (t['afterNoChange'] as List).isEmpty ? isEmpty : anything);
      expect(removedInst, isNotNull);
    });

    test('derived recompute + clear', () async {
      final t = _truth()['derived'] as Map<String, dynamic>;
      final logger = dl.DevToolsLogger.getInstance();
      final cap = _Capture(logger);
      final notifications = _notifications(logger);
      final src = ov.observableValue<int, Object?>('dsrc', 1);
      final dv = d.derived<int, Object?>(
          (reader) => reader.readObservable(src) * 2);
      logger.handleObservableCreated(dv, _loc('loc2', 'file.ts', 20, 3));
      await _flush(notifications);
      logger.handleOnListenerCountChanged(dv, 1);
      await _flush(notifications);
      cap.clear();

      logger.handleDerivedDependencyChanged(dv, src, null);
      logger.handleObservableUpdated(dv, IChangeInformation(
        hadValue: true, oldValue: 2, newValue: 4, change: null, didChange: true));
      await _flush(notifications);
      final rInst = cap.instanceWith('recomputationCount');
      cap.clear();

      logger.handleDerivedCleared(dv);
      await _flush(notifications);
      final clearInst = cap.instanceMatching(
          (v) => v is Map && (v.isEmpty || v['formattedValue'] == null));
      cap.clear();

      final expR = ((t['afterRecompute'] as List).first as Map)['state']
          as Map<String, dynamic>;
      final expRInst = (expR['instances'] as Map).values.first as Map;
      expect(rInst, isNotNull);
      expect(rInst!['formattedValue'], expRInst['formattedValue']);
      expect(rInst['recomputationCount'], expRInst['recomputationCount']);
      expect(clearInst, isNotNull);
    });

    test('autorun finished + disposed', () async {
      final t = _truth()['autorun'] as Map<String, dynamic>;
      final logger = dl.DevToolsLogger.getInstance();
      final cap = _Capture(logger);
      final notifications = _notifications(logger);
      final ar = au.autorun((reader) {});
      logger.handleAutorunCreated(ar, _loc('loc1', 'file.ts', 10, 5));
      await _flush(notifications);
      cap.clear();
      final src = ov.observableValue<int, Object?>('asrc', 1);
      logger.handleAutorunDependencyChanged(ar, src, null);
      logger.handleAutorunStarted(ar);
      logger.handleAutorunFinished(ar);
      await _flush(notifications);
      final fInst = cap.instanceWith('runCount');
      cap.clear();

      logger.handleAutorunDisposed(ar);
      await _flush(notifications);
      final disposedInst = cap.instanceMatching((v) => v == null);
      cap.clear();

      final expF = ((t['afterFinished'] as List).first as Map)['state']
          as Map<String, dynamic>;
      final expFInst = (expF['instances'] as Map).values.first as Map;
      expect(fInst, isNotNull);
      expect(fInst!['runCount'], expFInst['runCount']);
      expect(disposedInst, isNotNull);
    });

    test('transaction getTransactionState during/after', () {
      final t = _truth()['transaction'] as Map<String, dynamic>;
      final logger = dl.DevToolsLogger.getInstance();
      _Capture(logger);
      final tx = TransactionImpl((_) {}, () => 'myTx');
      logger.handleBeginTransaction(tx);
      final during = logger.getTransactionState();
      logger.handleEndTransaction(tx);
      final after = logger.getTransactionState();

      final expDuring = t['during'] as Map<String, dynamic>;
      expect(during, isNotNull);
      expect(during!.names, expDuring['names']);
      expect(during.affected.length, expDuring['affectedCount']);
      expect(after, null);
      expect('undefined', t['after']);
    });
  });
}
